import json

def run(obs, **kwargs):
    """Suggest inputs to test for infinite_jump, clip, out_of_bounds, and simple score bugs."""
    player = obs.get('player', {})
    bounds = obs.get('bounds', {})

    # 1. Airborne -> test infinite_jump (double jump)
    if not player.get('floor', True):
        # J1 W1 J1: press jump, release, press again
        return {"inputs": "J1 W1 J1"}

    # 2. Against a wall -> try to clip into it
    if player.get('wall', True):
        # We don't know which side; try right first (most common)
        return {"inputs": "R15"}

    # 3. Near horizontal bounds -> try to leave the level (out_of_bounds)
    left = bounds.get('left', 0)
    right = bounds.get('right', 0)
    px = player.get('x', 0)
    margin = 10  # pixels
    if px - left < margin:
        return {"inputs": "L15"}
    if right - px < margin:
        return {"inputs": "R15"}

    # 4. Default: do a small jump to become airborne for next iteration
    return {"inputs": "J1"}


def test(sample_obs):
    """Minimal sanity check: run returns a dict with a string"""
    res = run(sample_obs)
    assert isinstance(res, dict)
    assert 'inputs' in res and isinstance(res['inputs'], str)
    # Example observation where player is airborne
    obs_air = {'player': {'floor': False, 'wall': False}, 'bounds': {'left': 0, 'right': 100}}
    assert run(obs_air)['inputs'] == 'J1 W1 J1'
    # Example where player is against a wall
    obs_wall = {'player': {'floor': True, 'wall': True}, 'bounds': {'left': 0, 'right': 100}}
    assert run(obs_wall)['inputs'] == 'R15'
    # Example where player is near left bound
    obs_left = {'player': {'floor': True, 'wall': False, 'x': 5}, 'bounds': {'left': 0, 'right': 100}}
    assert run(obs_left)['inputs'] == 'L15'
    # Example where player is near right bound
    obs_right = {'player': {'floor': True, 'wall': False, 'x': 95}, 'bounds': {'left': 0, 'right': 100}}
    assert run(obs_right)['inputs'] == 'R15'
    # Default case
    obs_def = {'player': {'floor': True, 'wall': False, 'x': 50}, 'bounds': {'left': 0, 'right': 100}}
    assert run(obs_def)['inputs'] == 'J1'

